package pmap

import (
	"strconv"
	"sync/atomic"
	"testing"
	"time"
)

func seq(n int) []int {
	s := make([]int, n)
	for i := range s {
		s[i] = i
	}
	return s
}

func TestParallelMapOrder(t *testing.T) {
	cases := []struct {
		name    string
		in      []int
		workers int
	}{
		{"kosong", []int{}, 3},
		{"satu worker", []int{1, 2, 3}, 1},
		{"worker lebih banyak dari item", []int{4, 5}, 10},
		{"banyak item", seq(50), 4},
		{"worker nol dianggap satu", []int{7, 8, 9}, 0},
		{"worker negatif dianggap satu", []int{2, 3}, -5},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got := ParallelMap(c.in, c.workers, func(n int) string { return strconv.Itoa(n * n) })
			if len(got) != len(c.in) {
				t.Fatalf("len(got) = %d, want %d", len(got), len(c.in))
			}
			for i, n := range c.in {
				if want := strconv.Itoa(n * n); got[i] != want {
					t.Errorf("got[%d] = %q, want %q", i, got[i], want)
				}
			}
		})
	}
}

func TestParallelMapLimit(t *testing.T) {
	cases := []struct {
		name    string
		workers int
		minPeak int32
	}{
		{"satu worker berjalan berurutan", 1, 1},
		{"tiga worker berjalan paralel", 3, 2},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			var running, peak int32
			ParallelMap(seq(20), c.workers, func(n int) int {
				cur := atomic.AddInt32(&running, 1)
				for {
					old := atomic.LoadInt32(&peak)
					if cur <= old || atomic.CompareAndSwapInt32(&peak, old, cur) {
						break
					}
				}
				time.Sleep(5 * time.Millisecond)
				atomic.AddInt32(&running, -1)
				return n
			})
			p := atomic.LoadInt32(&peak)
			if p > int32(c.workers) {
				t.Errorf("peak concurrency = %d, want <= %d", p, c.workers)
			}
			if p < c.minPeak {
				t.Errorf("peak concurrency = %d, want >= %d", p, c.minPeak)
			}
			if r := atomic.LoadInt32(&running); r != 0 {
				t.Errorf("%d calls still running after ParallelMap returned", r)
			}
		})
	}
}

