package pmap

import "sync"

func ParallelMap[T, R any](in []T, workers int, f func(T) R) []R {
	if workers < 1 {
		workers = 1
	}
	out := make([]R, len(in))
	jobs := make(chan int)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = f(in[i])
			}
		}()
	}
	for i := range in {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}
